from dotenv import load_dotenv
load_dotenv()

from langchain.chat_models import init_chat_model

model = init_chat_model("deepseek:deepseek-v4-flash", temperature=0)

# 用字典描述工具（OpenAI function calling 格式）
tools = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "查询指定城市的天气",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "城市名称，如 杭州、北京"
                    }
                },
                "required": ["city"]
            }
        }
    }
]

# bind_tools() 将工具绑定到模型
# 模型现在"知道"有 get_weather 这个工具可用
model_with_tools = model.bind_tools(tools)

# 问一个需要工具的问题
response = model_with_tools.invoke("杭州今天天气怎么样？")

# 检查模型是否请求调用工具
if response.tool_calls:
    print("模型请求调用以下工具：")
    for tc in response.tool_calls:
        print(f"  工具名: {tc['name']}")
        print(f"  参数: {tc['args']}")
        print(f"  调用ID: {tc['id']}")
else:
    print(f"模型直接回复: {response.content}")

chapters.body:
工具（Tool）是 Agent 与外部世界交互的桥梁。
通过 @tool 装饰器，你可以将任何 Python 函数快速转换为 Agent 可调用的工具。
@tool 基本语法
@tool 是 LangChain 提供的装饰器，用法极其简单：在函数上加上 @tool 装饰器，函数就变成了一个工具。
实例

examples:
from langchain.tools import tool, InjectedState, InjectedStore, ToolException
from typing import Annotated
from langgraph.store.base import BaseStore

# 基本工具
@tool
def my_tool(param: str) -> str:
    """工具描述"""
    return f"结果: {param}"

# 带参数校验
from pydantic import BaseModel, Field

class MyInput(BaseModel):
    param: str = Field(description="参数说明", min_length=1)

@tool(args_schema=MyInput)
def validated_tool(param: str) -> str:
    return param

# 直接返回
@tool(return_direct=True)
def query_tool(query: str) -> str:
    return f"结果: {query}"

# 注入状态
@tool
def stateful_tool(
    param: str,
    state: Annotated[dict, InjectedState],
) -> str:
    return f"消息数: {len(state.get('messages', []))}"

# 注入 Store
@tool
def store_tool(
    key: str,
    store: Annotated[BaseStore, InjectedStore()],
) -> str:
    item = store.get(("ns",), key)
    return str(item.value if item else "无")

# 异常处理
@tool
def safe_tool(param: int) -> str:
    if param < 0:
        raise ToolException(f"参数必须为正数: {param}")
    return f"OK: {param}"

